insert into org.decisao_registrada (circulo, ordem, decisao, origem, efeito) select circulo, ordem, decisao, origem, efeito from jsonb_to_recordset($j$[{"circulo": 1, "ordem": 1, "decisao": "A Identidade padroniza, normatiza e sistematiza; os outros círculos executam", "origem": "Regra sua (12:29), aplicada às treze jornadas por proposta minha, que você aprovou (12:59)", "efeito": "O círculo fica com cinco jornadas; oito são transferidas a quem executa."}, {"circulo": 1, "ordem": 2, "decisao": "O Soul Brand é insumo, não o centro das jornadas", "origem": "Orientação sua (10:01)", "efeito": "Ele é a declaração de identidade em vigor: saída da ID-01 e entrada das demais."}, {"circulo": 1, "ordem": 3, "decisao": "Comunicação interna fica na Gestão; a externa, em Relações", "origem": "Decisão sua (12:29) para a interna; a externa segue a decisão D3 da rodada 2", "efeito": "A Identidade entrega voz, mensagens e o aviso do que mudou."}, {"circulo": 1, "ordem": 4, "decisao": "Auditoria das entregas fica na Governança, com interoperabilidade com o que é cross", "origem": "Decisão sua (12:29)", "efeito": "A Identidade entrega critérios de auditoria e casos de teste e julga os casos de fronteira."}, {"circulo": 1, "ordem": 5, "decisao": "Integração cultural, rituais, reconhecimento e propósito pessoal ficam na parte de cultura e pessoas da Gestão", "origem": "Decisão sua (12:29), estendida por proposta minha aprovada (12:59)", "efeito": "A Identidade entrega o kit de cultura e pessoas."}, {"circulo": 1, "ordem": 6, "decisao": "Monitorar a reputação fica em Relações; responder a crises, na Governança com o executivo", "origem": "Proposta minha aprovada (12:59)", "efeito": "A Identidade entrega o protocolo de crise e tem assento no comitê."}, {"circulo": 1, "ordem": 7, "decisao": "O relato de impacto fica na Governança", "origem": "Proposta minha aprovada (12:59)", "efeito": "A Identidade define o que conta como impacto."}, {"circulo": 1, "ordem": 8, "decisao": "Material de marca é produzido por quem usa; uso por terceiros fica em Relações, com Governança", "origem": "Proposta minha aprovada (12:59)", "efeito": "A Identidade entrega o pacote de marca com modelos e a regra de uso por terceiros."}, {"circulo": 1, "ordem": 9, "decisao": "A Identidade mantém o ciclo de retorno e responde consultas em prazo combinado", "origem": "Condição proposta por mim e aprovada (12:59)", "efeito": "ID-05 avalia os padrões com os dados de quem mede; a etapa 1 da ID-02 responde consultas. O prazo ainda não foi definido."}, {"circulo": 1, "ordem": 10, "decisao": "Os padrões são obrigatórios", "origem": "Condição proposta por mim e aprovada (12:59)", "efeito": "Cada jornada que executa terá um ponto de conferência contra o padrão. Vale como requisito para os próximos círculos."}, {"circulo": 1, "ordem": 11, "decisao": "Quatro ajustes depois do fechamento: marca recebida e retirada de marca (ID-03); ramo “manter o atual” quando os sócios dizem não (ID-01 e ID-02); pesquisa de mercado vinda da Inteligência (ID-03); conferência da Governança nos limites dos agentes (ID-02)", "origem": "Propostas do revisor independente e do cruzamento com a Estratégia, aprovadas por você (15:48)", "efeito": "Aplicados nesta versão."}, {"circulo": 1, "ordem": 12, "decisao": "Reserva de domínios e registro de perfis da marca ficam na Identidade", "origem": "Decisão sua (15:48), contra a proposta do revisor", "efeito": "A ID-03 fica como estava nesse ponto."}, {"circulo": 1, "ordem": 13, "decisao": "O posicionamento institucional e a casa de mensagens passam a ir também à Inteligência", "origem": "Proposta do cruzamento com a Inteligência, aprovada por você (20:02)", "efeito": "A ID-04, etapa 5, entrega o posicionamento à Inteligência, que o usa para enquadrar cada oferta (IN-07, etapa 3)."}, {"circulo": 1, "ordem": 14, "decisao": "Na marca, a Identidade decide, ouvido o executivo; a retirada vale na data de efeito do pedido", "origem": "Duas propostas, aprovadas por você (20:11 de 02/10/2026)", "efeito": "Na ID-03, etapa 4, o executivo opina e a Identidade escolhe a identidade visual e verbal; na etapa 2, a retirada da marca é agendada para a data de efeito que vem no pedido da Estratégia."}, {"circulo": 1, "ordem": 15, "decisao": "O nível “workflow” passa a se chamar etapa; cada círculo tem o seu código", "origem": "Você usou “etapas” (10:01); o código por círculo é proposta minha, sem objeção", "efeito": "ID-01 a ID-05 aqui; ES-01 em diante na Estratégia."}, {"circulo": 1, "ordem": 16, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "De Autopiloto para Autômato, pelas tarefas: ID-04 etapa 5. De Copiloto para Assistido, pelas tarefas: ID-01 etapa 1, ID-01 etapa 2, ID-03 etapa 2, ID-03 etapa 3, ID-03 etapa 4, ID-04 etapa 2. Nível de automação pela faixa: ID-01 baixa → média; ID-02 alta nas consultas, média na redação → média (alta nas consultas, média na redação); ID-04 média → baixa; ID-05 média → alta."}, {"circulo": 1, "ordem": 17, "decisao": "Você lidera a Identidade até os padrões estarem codificados", "origem": "Tema P2, decidido por você (13:09 de 03/10/2026)", "efeito": "O líder do círculo Identidade é você; a troca de liderança volta a decisão quando os padrões estiverem codificados."}, {"circulo": 1, "ordem": 18, "decisao": "Critério de decisão e limites dos agentes", "origem": "Aprovado por você (13:51 de 03/10/2026), a aprovar pelos sócios na ID-02", "efeito": "Agente sem tarefa de julgamento; etapa sem pessoa no caminho principal só em risco baixo ou médio, com auditoria por amostra no médio (P6); liberação com teste e alçada conferida pela Governança; suspensão quando a auditoria aponta desvio."}, {"circulo": 1, "ordem": 19, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "ID-05 semestral. O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 2, "ordem": 1, "decisao": "A Estratégia faz o trabalho de estratégia de ponta a ponta, os sócios aprovam e a Gestão opera a rotina", "origem": "Regra sua (15:48), sobre a minha proposta", "efeito": "A Estratégia formula, propõe, desdobra, decide os portões dentro da alçada e acompanha. Li “rotina” como montar e controlar o orçamento e rodar o ritual de acompanhamento dos alvos; leitura confirmada por você às 20:11 de 02/10/2026."}, {"circulo": 2, "ordem": 2, "decisao": "O executivo e o líder do círculo propõem e participam, mas não decidem", "origem": "Regra sua (20:02), ao aprovar a proposta 1", "efeito": "Na ES-01, etapa 3, a Estratégia formula a estratégia de cada empresa e as escolhas de cada círculo, ouvidos o executivo e o líder; a divergência sem acordo sobe aos sócios, e a decisão deles é incorporada ao texto na etapa 5. Desde as 20:11 de 02/10/2026 a regra vale também na ES-02 (mudança de papel), na ES-04 (portão e data de saída) e na ES-06 (correções de execução): o executivo opina numa tarefa própria e a Estratégia decide; acima da alçada, decidem os sócios."}, {"circulo": 2, "ordem": 3, "decisao": "A Integração é o PMO corporativo, interno e externo", "origem": "Definição sua (15:48)", "efeito": "Na ES-05 a Integração executa o mandato e a Estratégia confere; na ES-03 confere a capacidade de executar as iniciativas; na ES-04 coordena o lançamento da oferta aprovada (ponto 3 do círculo 3, aprovado às 20:02) e o plano de saída de clientes e contratos. Vale como requisito para o círculo 6."}, {"circulo": 2, "ordem": 4, "decisao": "Sobem para os sócios: a estratégia, a alocação e o destino do resultado, os alvos com o orçamento, e criar, adquirir, vender ou encerrar empresa", "origem": "Proposta minha aprovada (15:48), completada pelas propostas 3, 4, 6 e 13 (20:02) e pelas mudanças aprovadas às 20:11 de 02/10/2026", "efeito": "ES-01, ES-02, ES-03 e ES-05 têm etapa de aprovação pelos sócios. Sobem também o método de estratégia e as hipóteses, a proposta de manter a estratégia e a de manter a alocação, as divergências sem acordo, a autorização para negociar e a proposta de arquivar caso que os sócios mandaram estudar ou cuja negociação autorizaram. Na ES-04 só sobe o que passa da alçada da Estratégia."}, {"circulo": 2, "ordem": 5, "decisao": "Os sócios autorizam a negociação, com limites, antes de ela começar", "origem": "Proposta 13, aprovada por você (20:02)", "efeito": "A ES-05 ganha a etapa 2. O contrato de compra ou venda é preparado pela Governança e assinado depois da decisão dos sócios e antes do mandato (etapa 5)."}, {"circulo": 2, "ordem": 6, "decisao": "Uma aposta atravessa dois portões: a entrada na carteira e o lançamento", "origem": "Sua decisão D4 da rodada 2, confirmada (15:48)", "efeito": "A validação com clientes é marco da jornada da Inteligência. Encerrar é resultado possível de qualquer portão ou revisão."}, {"circulo": 2, "ordem": 7, "decisao": "A estratégia de experiência do cliente é de Relações", "origem": "Proposta minha aprovada (15:48)", "efeito": "Fica fora das jornadas da Estratégia. Entra no desenho do círculo 4, com Operações no círculo 7."}, {"circulo": 2, "ordem": 8, "decisao": "Vender ou encerrar uma empresa inclui retirar a marca de uso", "origem": "Decorre da proposta 1 do círculo 1, aprovada por você (15:48)", "efeito": "A ES-05 pede a retirada à Identidade, com a data de efeito, e a ES-04 faz o mesmo pedido quando encerra oferta com marca própria. Desde as 20:11 de 02/10/2026, a ID-03 agenda a retirada para a data de efeito do pedido."}, {"circulo": 2, "ordem": 9, "decisao": "As 18 propostas de mudança deste círculo foram aprovadas", "origem": "Sua resposta das 20:02", "efeito": "Estão aplicadas nesta versão. Cada uma aparece na aba O que mudou com a marca “aprovada às 20:02”."}, {"circulo": 2, "ordem": 10, "decisao": "As cinco propostas da revisão de 02/10/2026 foram aprovadas", "origem": "Sua resposta das 20:11 de 02/10/2026 (“Tudo 100% aprovado”)", "efeito": "Estão aplicadas nesta versão, menos a troca do nome do método: o nome é recebido pela Inteligência (círculo 3) e ficou como estava. Cada uma aparece na aba O que mudou."}, {"circulo": 2, "ordem": 11, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "ES-05 etapa 3: acrescentada a tarefa da pessoa da Estratégia \"Consolidar o resultado da apuração para decidir se o caso segue\" (item 1). ES-03 etapa 3: acrescentada a tarefa da pessoa da Estratégia \"Confirmar se os alvos e as iniciativas cabem nos recursos\"; o modo segue Copiloto (item 2). De Assistido para Copiloto, pelas tarefas: ES-04 etapa 3, ES-04 etapa 4. De Autopiloto para Autômato, pelas tarefas: ES-03 etapa 5. De Copiloto para Assistido, pelas tarefas: ES-01 etapa 2, ES-03 etapa 2, ES-05 etapa 4, ES-06 etapa 3. Nível de automação pela faixa: ES-01 baixa → média; ES-05 baixa → média; ES-06 média → alta."}, {"circulo": 2, "ordem": 12, "decisao": "Método de estratégia: calendário, portões, realocação e hipóteses", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "Calendário: ES-01 anual com revisão no meio do ciclo, ES-02 semestral, ES-03 anual, ES-06 trimestral, GE-02 mensal, ES-04 por evento. Portão 1 (entrar na carteira): problema e público claros, coerência com a identidade, hipótese testável com indicador, próximo passo dentro da reserva, dono. Portão 2 (lançar): evidência de demanda, preço-base que cobre o custo, capacidade confirmada, contrato no modelo, indicadores definidos. Realocação por resultado contra o alvo e coerência: crescer, manter, reduzir ou estudar a saída. Alçada da aposta: cada aposta dentro da reserva dos sócios, até um terço dela."}, {"circulo": 3, "ordem": 1, "decisao": "A Inteligência decide o que é técnico do seu ofício", "origem": "Ponto 1, aprovado por você (20:02)", "efeito": "Decide a ficha de cada dado e de cada indicador, o método, a curadoria das bases e a conclusão de cada análise e de cada piloto. Se o dono não confirma a ficha, vale a da Inteligência, com a divergência registrada; no indicador de alvo, decide a Estratégia. Fora do seu ofício e da oferta entre os portões, ela propõe ou recomenda."}, {"circulo": 3, "ordem": 2, "decisao": "Entre os dois portões, a decisão é da Inteligência; o executivo pode sugerir", "origem": "Decisão sua (20:02), contra a minha proposta", "efeito": "Na IN-07, a Inteligência decide o enquadramento, o desenho, o modelo de negócio com o preço-base, as condições do piloto, o caminho depois dele e o pacote. O executivo, Negócios e a Gestão opinam. Negócios mantém a tabela de preços e a política comercial, redige os termos e fecha o piloto; a Governança revê os termos."}, {"circulo": 3, "ordem": 3, "decisao": "A Integração acompanha o desenvolvimento e coordena o lançamento da oferta", "origem": "Ponto 3, aprovado por você (20:02)", "efeito": "A Inteligência lidera o conteúdo até o portão de lançamento, e a Integração, como PMO corporativo, acompanha o desenvolvimento na carteira de projetos. Depois do portão, a Integração coordena o lançamento com o executivo; Relações gera a demanda e Negócios vende."}, {"circulo": 3, "ordem": 4, "decisao": "Uma amostra só, sorteada pela Governança", "origem": "Ponto 4, aprovado por você (20:02)", "efeito": "A Inteligência avalia o resultado em cada amostra recebida, pelo critério de sucesso do método (IN-06, etapa 5). Não sorteia amostra própria."}, {"circulo": 3, "ordem": 5, "decisao": "O ajuste de oferta em uso não passa pelo portão; a revisão passa", "origem": "Ponto 5: você aprovou a alternativa que recomendei (20:02)", "efeito": "Na IN-07, etapa 2, a Inteligência decide, ouvido o executivo, se o pedido é ajuste ou revisão. O ajuste, que não muda problema, público, modelo nem preço-base, é feito ali mesmo, só no que muda, e vai direto ao catálogo de ofertas. A revisão volta ao portão de entrada. Tratar a mudança de preço-base como revisão foi confirmado por você às 20:11 de 02/10/2026."}, {"circulo": 3, "ordem": 6, "decisao": "O círculo fica com oito jornadas", "origem": "Ponto 6, aprovado por você (20:02)", "efeito": "IN-01 a IN-08, sem fusão."}, {"circulo": 3, "ordem": 7, "decisao": "As mudanças que este círculo pediu aos círculos 1 e 2 foram aprovadas", "origem": "Sua resposta das 20:02", "efeito": "Uma no círculo 1 e 18 no círculo 2, aplicadas nas páginas deles. Aqui mudaram os nomes dos produtos trocados com a Estratégia, e a IN-04 e a IN-07 ganharam inícios novos: alvos propostos, decisão sobre contestação, decisão sobre aposta devolvida, mandato de saída de empresa e pedido sobre oferta em uso."}, {"circulo": 3, "ordem": 8, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "De Assistido para Copiloto, pelas tarefas: IN-03 etapa 5, IN-06 etapa 3, IN-07 etapa 8. De Autopiloto para Autômato, pelas tarefas: IN-07 etapa 9. De Copiloto para Assistido, pelas tarefas: IN-07 etapa 2, IN-07 etapa 3, IN-07 etapa 5. Nível de automação pela faixa: IN-01 média → alta; IN-03 alta → média; IN-08 média → alta."}, {"circulo": 3, "ordem": 9, "decisao": "O limite do ajuste de oferta em uso é decidido pela Estratégia", "origem": "Decidido por você (13:09 de 03/10/2026)", "efeito": "IN-07: o ajuste dentro do limite dispensa o portão; quem fixa o limite é a Estratégia, que já decide a oferta lançada."}, {"circulo": 3, "ordem": 10, "decisao": "Limite do ajuste de oferta em uso", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "O ajuste dispensa o portão se não muda o público, a promessa central nem o escopo principal, não reduz o preço-base, não pede capacidade nova e não muda o risco do contrato-modelo; senão, vai ao portão (ES-04)."}, {"circulo": 3, "ordem": 11, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "IN-01 mensal; IN-04 medição mensal e revisão anual; IN-05 trimestral; IN-08 trimestral. O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 4, "ordem": 1, "decisao": "Relações decide o que é do seu ofício; o executivo e Negócios opinam", "origem": "Ponto 1, aprovado por você (19:05)", "efeito": "Relações decide o plano de demanda, a qualificação de cada oportunidade, a estratégia de experiência do cliente, a pauta e o conteúdo externo e as parcerias dentro da alçada. O executivo aprova o que se diz em nome da empresa e quem fala por ela."}, {"circulo": 4, "ordem": 2, "decisao": "O critério de oportunidade qualificada é combinado com Negócios; sem acordo, decide o executivo", "origem": "Ponto 2, aprovado por você (19:05)", "efeito": "Relações e Negócios combinam o critério a cada ciclo de demanda (RE-01, etapa 2). Negócios aceita ou devolve cada oportunidade com o motivo (RE-03). É a única exceção do círculo à regra de que o executivo opina e não decide."}, {"circulo": 4, "ordem": 3, "decisao": "Relações acompanha o sucesso do cliente; Negócios renova e amplia; Operações atende e entrega", "origem": "Ponto 3, aprovado por você (19:05)", "efeito": "O plano de sucesso (RE-05) é a referência comum dos três círculos que falam com o cliente."}, {"circulo": 4, "ordem": 4, "decisao": "O executivo aprova o que fala em nome da empresa; a Governança confere o risco jurídico", "origem": "Ponto 4, aprovado por você (19:05)", "efeito": "Relações decide a pauta e aprova o conteúdo dentro dos padrões (RE-07). Na crise, a posição é do comitê da Governança, com o executivo (RE-08)."}, {"circulo": 4, "ordem": 5, "decisao": "O uso da marca por terceiros fica na RE-06, etapa 5", "origem": "Ponto 5, aprovado por você (19:05)", "efeito": "A regra é da Identidade. Relações decide o uso coberto pela regra e, fora dela, a exceção ouvida a Identidade; a Governança libera antes da autorização."}, {"circulo": 4, "ordem": 6, "decisao": "Relações forma e acompanha o parceiro de venda; Negócios vende com ele", "origem": "Ponto 6, aprovado por você (19:05)", "efeito": "A relação institucional sem contrato segue a mesma jornada e a mesma alçada; a Governança confere o termo e o executivo o aprova (RE-06)."}, {"circulo": 4, "ordem": 7, "decisao": "Oito jornadas", "origem": "Ponto 7, decidido por mim, como você pediu (19:05)", "efeito": "Mantive a proposta. Planejar e executar a demanda têm cadência diferente (ciclo e ação), e desenhar a experiência de todos os clientes é trabalho distinto de cuidar de cada cliente. Juntar daria seis jornadas maiores, com gatilhos misturados."}, {"circulo": 4, "ordem": 8, "decisao": "As três propostas aos círculos 2 e 3 foram aceitas e aplicadas", "origem": "Decisão sua (19:05)", "efeito": "IN-07, etapa 4, recebe a estratégia de experiência do cliente (RE-04). IN-03, etapa 2, recebe a situação do funil e a base de relacionamento (RE-03) e o resultado das ações de demanda (RE-02). ES-04 avisa Relações da aposta mantida, em espera, devolvida ou encerrada (etapa 3): a RE-05 desfaz a transição preparada e a RE-06 responde ao parceiro. A parceria aprovada no portão volta a Relações (etapa 5) e a RE-06 a formaliza."}, {"circulo": 4, "ordem": 9, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "RE-03 etapa 1: na dúvida sobre a base legal, a pessoa de Relações decide (item 8). De Assistido para Copiloto, pelas tarefas: RE-06 etapa 2. De Autopiloto para Autômato, pelas tarefas: RE-02 etapa 2, RE-03 etapa 4. De Copiloto para Assistido, pelas tarefas: RE-01 etapa 2, RE-03 etapa 3, RE-06 etapa 4. Nível de automação pela faixa: RE-02 alta na execução, média na preparação → média (alta na execução, média na preparação); RE-08 alta na coleta, baixa na crise → média (alta na coleta, baixa na crise)."}, {"circulo": 4, "ordem": 10, "decisao": "Alçada de parceria", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "Relações decide parceria sem exclusividade, com remuneração na regra dos sócios, marca pelo pacote, prazo até o fim do ciclo estratégico e sem obrigação além do orçamento do círculo; fora disso, os sócios."}, {"circulo": 4, "ordem": 11, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "Cadências de RE-01 a RE-08; critério de oportunidade qualificada (quatro condições), regra de saúde do cliente (três sinais) e critério de crise (quatro gatilhos). O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 5, "ordem": 1, "decisao": "Negócios decide o seu ofício; o executivo opina, aprova a concessão acima da alçada de quem vende e assina", "origem": "Ponto 1, aprovado por você (20:11)", "efeito": "Acima da alçada do executivo, decidem os sócios. A faixa de desconto de quem vende é aprovada pela Governança. A oportunidade de parceiro de venda é conferida por Negócios com o critério combinado com Relações, sem passar pela qualificação de Relações."}, {"circulo": 5, "ordem": 2, "decisao": "O preço de tabela fica no preço-base ou acima dele", "origem": "Ponto 2, aprovado por você (20:11)", "efeito": "Abaixo, Negócios pede à Inteligência a revisão do preço-base e mantém a oferta no preço vigente até a resposta (NE-01). Você confirmou também que mudar o preço-base de oferta em uso é revisão, que volta ao portão de entrada."}, {"circulo": 5, "ordem": 3, "decisao": "Licitação é jornada própria; Negócios decide participar e recorrer, ouvidos o executivo e a Governança", "origem": "Ponto 3, aprovado por você (20:11)", "efeito": "NE-05, nas fases da Lei 14.133. A Governança confere a habilitação e conduz esclarecimentos, impugnações, recursos e contrarrazões; o executivo assina."}, {"circulo": 5, "ordem": 4, "decisao": "A divisão na oferta conjunta é dos executivos das duas empresas", "origem": "Ponto 4, aprovado por você (20:11)", "efeito": "Exceção declarada à regra de que o executivo opina. A Gestão confere o efeito no resultado de cada empresa e a Governança formaliza o acordo antes da proposta (NE-07)."}, {"circulo": 5, "ordem": 5, "decisao": "A previsão de receita e o desdobramento dos alvos de venda são de Negócios", "origem": "Ponto 5, aprovado por você (20:11)", "efeito": "NE-02, a partir dos alvos do ciclo, do funil e dos contratos; a previsão vai à Gestão, a Operações, à Integração e ao executivo."}, {"circulo": 5, "ordem": 6, "decisao": "O pedido de cancelamento é tratado por Negócios, como retenção", "origem": "Ponto 6, aprovado por você (20:11)", "efeito": "NE-06, etapa 2. Relações trata o risco de perda antes do pedido (RE-05)."}, {"circulo": 5, "ordem": 7, "decisao": "Sete jornadas", "origem": "Ponto 7, aprovado por você (20:11)", "efeito": "NE-01 a NE-07, como propostas."}, {"circulo": 5, "ordem": 8, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "De Assistido para Copiloto, pelas tarefas: NE-05 etapa 4. De Autopiloto para Autômato, pelas tarefas: NE-03 etapa 4. De Copiloto para Assistido, pelas tarefas: NE-02 etapa 2, NE-03 etapa 2, NE-06 etapa 2, NE-06 etapa 3, NE-07 etapa 2."}, {"circulo": 5, "ordem": 9, "decisao": "A regra de remuneração de quem vende e de parceiros é decidida pelos sócios", "origem": "Decidido por você (13:09 de 03/10/2026)", "efeito": "Negócios propõe com a Gestão; os sócios decidem, porque mexe em custo e incentivo de todas as empresas. Também: prazos da Lei 14.133 (arts. 84, 86, 90, 164 e 165) lidos em transcrição secundária e registrados nas fontes."}, {"circulo": 5, "ordem": 10, "decisao": "Alçada de concessão comercial", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "A NE-01 fixa, por oferta, a faixa entre o preço de tabela e o preço-base. Quem vende concede até metade da faixa; o executivo, até o preço-base e a condição de pagamento fora da política; os sócios decidem preço abaixo do preço-base, exclusividade e prazo maior que o ciclo estratégico. No contrato público, a concessão é a que o edital permite. A fração é escolha de desenho, a recalibrar com dados."}, {"circulo": 5, "ordem": 11, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "NE-01 semestral; NE-02 trimestral, com previsão mensal; NE-07 semestral; estrutura dos modelos de contrato e regra de remuneração. O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 6, "ordem": 1, "decisao": "A Integração decide o seu ofício; o executivo decide a prioridade dos projetos da sua empresa", "origem": "Ponto 1, aprovado por você (09:30 de 03/10/2026)", "efeito": "Método de projetos, arquitetura e plataforma, ficha técnica da capacidade, liberação do agente pelos testes e mudança em sistemas são da Integração, ouvidos os donos. A prioridade dos projetos de cada empresa é do executivo, exceção declarada que vem do documento-base."}, {"circulo": 6, "ordem": 2, "decisao": "O conflito de capacidade entre empresas sobe à Estratégia", "origem": "Ponto 2, aprovado por você (09:30)", "efeito": "IT-01, etapa 2."}, {"circulo": 6, "ordem": 3, "decisao": "A Integração libera o agente depois dos testes; a Governança confere a alçada; o líder do círculo dono aceita", "origem": "Ponto 3, aprovado por você (09:30)", "efeito": "IT-06, etapa 3. A Inteligência mede o acerto de conteúdo."}, {"circulo": 6, "ordem": 4, "decisao": "O líder do círculo dono decide o redesenho da jornada", "origem": "Ponto 4, aprovado por você (09:30)", "efeito": "IT-08. Os círculos por onde a jornada passa confirmam a sua parte; a Governança confere quando mexe em alçada, regra ou contrato."}, {"circulo": 6, "ordem": 5, "decisao": "A Integração decide o plano e a data do lançamento, ouvido o executivo", "origem": "Ponto 5, aprovado por você (09:30)", "efeito": "IT-03. O lançamento só sai com a prontidão conferida."}, {"circulo": 6, "ordem": 6, "decisao": "O pedido de serviço de uma empresa aos círculos fica na IT-05", "origem": "Ponto 6, aprovado por você (09:30)", "efeito": "Com acordo de serviço combinado com o líder do círculo dono. O rateio fica para a consolidação das jornadas entre empresas."}, {"circulo": 6, "ordem": 7, "decisao": "Oito jornadas", "origem": "Ponto 7, aprovado por você (09:30)", "efeito": "IT-01 a IT-08, como propostas."}, {"circulo": 6, "ordem": 8, "decisao": "A NE-01 recebe o plano de lançamento", "origem": "Proposta aprovada por você (09:30)", "efeito": "Aplicada no círculo 5: a IT-03 entrega o plano a Negócios."}, {"circulo": 6, "ordem": 9, "decisao": "A IT-04 recebe de Operações as entregas encerradas na saída", "origem": "Proposta do círculo 7, aprovada por você às 11:50 de 03/10/2026", "efeito": "IT-04, etapa 2: a conclusão da parte de Operações na saída passa a ser uma entrada, vinda da OP-08."}, {"circulo": 6, "ordem": 10, "decisao": "A IT-06 recebe da Governança o desvio de agente apontado pela auditoria", "origem": "Proposta do círculo 9, aprovada por você às 11:50 de 03/10/2026", "efeito": "IT-06, etapa 4: o desvio achado na auditoria (GO-06) entra no tratamento de desvio, como o achado pelo monitoramento."}, {"circulo": 6, "ordem": 11, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "IT-08 etapa 1: o agente propõe as jornadas do ciclo e a pessoa da Integração decide; o modo passa de Autopiloto a Copiloto (item 3). De Autopiloto para Autômato, pelas tarefas: IT-05 etapa 3, IT-06 etapa 4, IT-08 etapa 3. De Copiloto para Assistido, pelas tarefas: IT-01 etapa 4, IT-02 etapa 1, IT-02 etapa 3, IT-03 etapa 1, IT-05 etapa 2, IT-06 etapa 3, IT-08 etapa 2. Nível de automação pela faixa: IT-04 baixa → média; IT-05 média → alta; IT-06 média → alta; IT-07 alta → média; IT-08 média → alta."}, {"circulo": 6, "ordem": 12, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "IT-01 mensal; IT-05 trimestral; IT-06 mensal; IT-08 trimestral; método de projetos, prioridade da carteira, critério de liberação de agente (cinco testes) e política de segurança. O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 7, "ordem": 1, "decisao": "Operações decide o seu ofício; o executivo decide o que passa da alçada e o recall", "origem": "Ponto 1, aprovado por você (11:50 de 03/10/2026)", "efeito": "Plano de capacidade, plano de entrega, procedimentos e níveis de serviço, solução de reclamação dentro da alçada e ação corretiva são de Operações. Segue a regra dos outros círculos: o executivo decide só o que passa da alçada."}, {"circulo": 7, "ordem": 2, "decisao": "Relações define os padrões de experiência; Operações define os níveis de serviço", "origem": "Ponto 2, aprovado por você (11:50)", "efeito": "OP-05, etapa 1: Operações traduz a experiência e o método em procedimentos e níveis de serviço por oferta e por segmento. O padrão que não consegue cumprir volta a Relações como lacuna."}, {"circulo": 7, "ordem": 3, "decisao": "Operações trata todas as reclamações sobre entrega e atendimento", "origem": "Ponto 3, aprovado por você (11:50)", "efeito": "OP-04. Relações recebe cada reclamação com a causa (RE-04 e RE-08); a Governança avalia o risco legal e o dever de comunicar a autoridade."}, {"circulo": 7, "ordem": 4, "decisao": "Operações confirma a entrega; a Gestão fatura e compra", "origem": "Ponto 4, aprovado por você (11:50)", "efeito": "Como diz o documento-base: Operações não fatura. OP-02 e OP-06 passam as entregas confirmadas a faturar; OP-06 pede a compra dos materiais."}, {"circulo": 7, "ordem": 5, "decisao": "O pedido comercial que chega ao atendimento vai a Negócios sem passar por Relações", "origem": "Ponto 5, aprovado por você (11:50)", "efeito": "OP-03, etapa 1: tarefa de Negócios, que o trata na proposta ou no contrato (NE-03 e NE-06). Nenhuma mudança nos círculos fechados."}, {"circulo": 7, "ordem": 6, "decisao": "Produto físico em duas jornadas recomendadas", "origem": "Ponto 6, aprovado por você (11:50)", "efeito": "OP-06 e OP-07 só existem onde a oferta tem produto físico. O recall é decidido pelo executivo."}, {"circulo": 7, "ordem": 7, "decisao": "Oito jornadas", "origem": "Ponto 7, aprovado por você (11:50)", "efeito": "OP-01 a OP-08."}, {"circulo": 7, "ordem": 8, "decisao": "A IT-04 recebe de Operações as entregas encerradas na saída", "origem": "Proposta ao círculo 6, aprovada por você (11:50)", "efeito": "IT-04, etapa 2: a conclusão da parte de Operações passa a ser uma entrada, vinda da OP-08, etapa 3."}, {"circulo": 7, "ordem": 9, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "OP-08 etapa 3: a automação registra a liberação de pessoas, agentes, parceiros e ativos (item 4). OP-07 etapa 1: o agente faz a triagem e a pessoa de Operações decide se há risco à saúde ou à segurança; na dúvida, vai à avaliação de recall. A negativa de cobertura apontada pelo agente é revisada pela pessoa antes da resposta ao cliente. O modo passa de Autopiloto a Copiloto (itens 5 e 6). De Assistido para Copiloto, pelas tarefas: OP-07 etapa 3. De Autopiloto para Autômato, pelas tarefas: OP-01 etapa 3. De Copiloto para Assistido, pelas tarefas: OP-08 etapa 2, OP-07 etapa 2. Nível de automação pela faixa: OP-02 média → alta; OP-05 média → alta."}, {"circulo": 7, "ordem": 10, "decisao": "Fontes do pós-venda entre empresas e do recebimento público", "origem": "Pedido seu (13:09 de 03/10/2026): pesquisar e resolver as fontes", "efeito": "OP-07: Código Civil, arts. 421-A e 441 a 446; OP-02: Lei 14.133, art. 140. Lidos em transcrição secundária; conferir no oficial antes de usar em peça."}, {"circulo": 7, "ordem": 11, "decisao": "Alçadas de Operações", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "Falta de capacidade: Operações cobre com pessoas e parceiros já contratados, dentro do orçamento; contratação nova ou fora do orçamento vai ao executivo pela GE-01. Reclamação: Operações refaz e dá crédito até o valor faturado da entrega reclamada; acima, ou com responsabilidade e indenização, o executivo com a Governança."}, {"circulo": 7, "ordem": 12, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "OP-01 trimestral; OP-05 e OP-06 mensais; procedimento, três níveis de serviço e garantia por oferta. O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 8, "ordem": 1, "decisao": "A Gestão decide o seu ofício dentro da alçada; o executivo decide o que passa dela", "origem": "Ponto 1, aprovado por você (11:50 de 03/10/2026)", "efeito": "Mesma regra dos outros círculos. Os sócios aprovam alvos e orçamento (ES-03) e decidem alocação e destino do resultado (ES-02); a Gestão desdobra, controla e executa."}, {"circulo": 8, "ordem": 2, "decisao": "O líder decide quem entra na sua equipe; a Gestão conduz e confere", "origem": "Ponto 2, aprovado por você (11:50)", "efeito": "GE-07, etapa 2. O desligamento é decidido pelo executivo, com o líder, como exceção declarada na regra do círculo."}, {"circulo": 8, "ordem": 3, "decisao": "As quatro jornadas vindas da Identidade ficam como jornadas da Gestão, com o propósito pessoal dentro do desenvolvimento", "origem": "Ponto 3, aprovado por você (11:50)", "efeito": "Integração cultural (GE-08), rituais e reconhecimento (GE-10) e comunicação interna (GE-11), como transferidas em 01/10/2026; o propósito pessoal, que o destino da transferência já punha “dentro do ciclo de desenvolvimento”, virou etapa voluntária da GE-09, com o ajuste de papel só com o acordo da pessoa."}, {"circulo": 8, "ordem": 4, "decisao": "O rateio é aplicado pela Gestão pelo critério da Governança", "origem": "Ponto 4, aprovado por você (11:50)", "efeito": "GE-06, como a fronteira da Estratégia já dizia. O executivo opina; a contestação do critério vai à Governança."}, {"circulo": 8, "ordem": 5, "decisao": "A Gestão confirma ao plano de capacidade os recursos que cabem no orçamento", "origem": "Ponto 5, aprovado por você (11:50)", "efeito": "GE-01, etapa 1. A contratação e a compra seguem na GE-07 e na GE-04."}, {"circulo": 8, "ordem": 6, "decisao": "A realocação entre empresas não é decidida na Gestão", "origem": "Ponto 6, aprovado por você (11:50)", "efeito": "O pedido acima da alçada vai ao executivo; entre empresas, fica registrado para a revisão do portfólio (ES-02), que lê a execução do orçamento."}, {"circulo": 8, "ordem": 7, "decisao": "A folha é jornada própria; a remuneração de parceiros é paga na jornada de compras e pagamentos", "origem": "Ponto 7, aprovado por você (11:50)", "efeito": "GE-13 e GE-04, como Negócios pediu: a remuneração de quem vende e de parceiros fica com a Gestão."}, {"circulo": 8, "ordem": 8, "decisao": "Treze jornadas", "origem": "Ponto 8, aprovado por você (11:50)", "efeito": "GE-01 a GE-13."}, {"circulo": 8, "ordem": 9, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "De Assistido para Copiloto, pelas tarefas: GE-02 etapa 2. De Autopiloto para Autômato, pelas tarefas: GE-01 etapa 3, GE-02 etapa 3, GE-07 etapa 4, GE-11 etapa 3. De Copiloto para Assistido, pelas tarefas: GE-06 etapa 2, GE-07 etapa 2, GE-08 etapa 2, GE-09 etapa 1, GE-10 etapa 2. Nível de automação pela faixa: GE-05 média → alta; GE-06 alta → média; GE-12 média → alta."}, {"circulo": 8, "ordem": 10, "decisao": "A regra de remuneração é dos sócios; fontes da folha e da escrituração", "origem": "Decidido e pedido por você (13:09 de 03/10/2026)", "efeito": "A Gestão aplica a regra que os sócios decidem. GE-13 e GE-07: CLT (arts. 74, 145, 459 e 477) e FGTS (art. 15); GE-05: Código Civil (arts. 1.179, 1.180 e 1.194). A regra fiscal depende do regime de cada empresa, que não está no modelo."}, {"circulo": 8, "ordem": 11, "decisao": "Alçadas da Gestão", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "Remanejamento dentro do círculo e da empresa sem mudar o total: Gestão; entre círculos, executivo; entre empresas, Estratégia; aumento do total, sócios. Cobrança privada: na segunda fatura vencida, proposta de suspensão ao executivo; contrato público segue a lei e o contrato. Pagamento só com pedido, recebimento e nota conferidos; quem lança não aprova; fora do orçamento, executivo; acima da reserva de contingência, sócios. Aportes e distribuição: só o que os sócios decidiram; contas e poderes bancários com o executivo e a Governança. Vaga no orçamento: Gestão com o líder; fora, executivo; desligamento de executivo ou líder, sócios."}, {"circulo": 8, "ordem": 12, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "Cadências da Gestão (fechamento, rateio, folha, avaliação, cultura, comunicação, inventário); políticas de cobrança, compras, remuneração e desenvolvimento; critério de rateio. O que depende de dado real ficou nos gates G1 a G9."}, {"circulo": 9, "ordem": 1, "decisao": "A Governança decide o seu ofício dentro da alçada; os sócios decidem as regras gerais e as alçadas dos executivos", "origem": "Ponto 1, aprovado por você (11:50 de 03/10/2026)", "efeito": "GO-01, etapa 2. Mesma regra dos outros círculos. O critério de rateio é definido pela Governança com a Estratégia, como a fronteira do círculo 2 diz; a Gestão aplica."}, {"circulo": 9, "ordem": 2, "decisao": "Uma amostra única de entregas serve à auditoria e à avaliação dos métodos", "origem": "Ponto 2, aprovado por você (11:50)", "efeito": "GO-06, etapa 1: a mesma amostra vai à Inteligência (IN-06, etapa 5). Encaminha o alerta do círculo 3: quem sorteia e para onde vai está definido; os estratos (inclusive as entregas com método publicado) e o tamanho ficam em aberto."}, {"circulo": 9, "ordem": 3, "decisao": "O comitê de crise é conduzido pela Governança, com o executivo", "origem": "Ponto 3, aprovado por você (11:50)", "efeito": "GO-08, como a transferência do círculo 1 e a RE-08 já diziam: Relações monitora e comunica; a Governança propõe e o executivo aprova a declaração, a posição e o encerramento; a Identidade tem assento no comitê."}, {"circulo": 9, "ordem": 4, "decisao": "O papel de encarregado de dados pessoais fica na Governança", "origem": "Ponto 4, aprovado por você (11:50)", "efeito": "GO-07: a Governança decide a resposta ao titular; Relações executa na base de relacionamento (RE-03) e quem guarda o dado executa o resto."}, {"circulo": 9, "ordem": 5, "decisao": "O relato sobre o executivo é decidido com os sócios", "origem": "Ponto 5, aprovado por você (11:50)", "efeito": "GO-09, etapa 2: a medida é decidida com o executivo; se ele, a Governança ou um sócio estiver envolvido, decidem os sócios não envolvidos."}, {"circulo": 9, "ordem": 6, "decisao": "As auditorias de identidade e de agentes viram uma só", "origem": "Ponto 6, aprovado por você (11:50)", "efeito": "GO-06 junta a ID-11 transferida e a I-GO3, com a causa encaminhada a quem corrige. A Identidade julga os casos de fronteira, como decidido no fechamento do círculo 1."}, {"circulo": 9, "ordem": 7, "decisao": "Dez jornadas", "origem": "Ponto 7, aprovado por você (11:50)", "efeito": "GO-01 a GO-10."}, {"circulo": 9, "ordem": 8, "decisao": "A IT-06 recebe da Governança o desvio de agente apontado pela auditoria", "origem": "Proposta ao círculo 6, aprovada por você (11:50)", "efeito": "IT-06, etapa 4."}, {"circulo": 9, "ordem": 9, "decisao": "Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem", "origem": "Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)", "efeito": "GO-05 etapa 1: a decisão sobre cláusula fora do modelo ou risco relevante passa à pessoa da Governança; o agente aponta as diferenças (item 9). De Autopiloto para Autômato, pelas tarefas: GO-01 etapa 3, GO-05 etapa 2, GO-06 etapa 1, GO-07 etapa 3, GO-09 etapa 4. Nível de automação pela faixa: GO-03 média → alta; GO-06 média → alta; GO-07 média → alta; GO-08 baixa → média; GO-09 baixa → média."}, {"circulo": 9, "ordem": 10, "decisao": "O apetite a risco é dos sócios; prazo de comunicação de incidente lido", "origem": "Decidido e pedido por você (13:09 de 03/10/2026)", "efeito": "GO-03: a Governança mantém a matriz de riscos; os sócios decidem o apetite a risco. GO-09: três dias úteis para comunicar a autoridade e o titular (Resolução CD/ANPD nº 15/2024, arts. 6º e 9º), em dobro para o agente de pequeno porte, lida em transcrição secundária. GO-05: Código Civil, arts. 421-A e 422."}, {"circulo": 9, "ordem": 11, "decisao": "O que a Governança decide sozinha e as regras gerais dos contratos", "origem": "Aprovado por você (13:51 de 03/10/2026)", "efeito": "A Governança decide sozinha as regras que aplicam regra geral aprovada, os modelos de proposta e contrato, sigilo, dados e guarda, a alçada de pessoas no círculo e de agentes no critério, a matriz de riscos dentro do apetite dos sócios, o rateio com a Estratégia e a amostra. Vão aos sócios as alçadas dos executivos, as regras gerais, as exceções e a alçada da própria Governança. Regras gerais dos contratos: modelo obrigatório; assina o executivo; alocação de riscos escrita (Código Civil, art. 421-A); garantia escrita; papéis de dados e aviso de incidente a tempo dos três dias úteis; reajuste anual por índice escrito (recomendado o IPCA); exclusividade, prazo longo, multa acima do modelo, foro e garantia financeira vão aos sócios; contrato público usa a minuta do edital."}, {"circulo": 9, "ordem": 12, "decisao": "Cadências e conteúdos validados; gates de implantação", "origem": "Validado por você (14:07 de 03/10/2026)", "efeito": "GO-01 anual; GO-02 e GO-03 trimestrais; GO-06 trimestral; matriz de riscos 5 por 5, desenho da amostra e regras de sigilo, dados e guarda. O que depende de dado real ficou nos gates G1 a G9."}]$j$::jsonb) as x(circulo smallint, ordem smallint, decisao text, origem text, efeito text);
